PRAGMA foreign_keys=ON;
CREATE TABLE users(id TEXT PRIMARY KEY,name TEXT NOT NULL,email TEXT NOT NULL UNIQUE,password_salt TEXT NOT NULL,password_hash TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'customer' CHECK(role IN('customer','seller','admin')),referral_code TEXT NOT NULL UNIQUE,referred_by TEXT REFERENCES users(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE sessions(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,token_hash TEXT NOT NULL UNIQUE,expires_at TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX sessions_token_idx ON sessions(token_hash);
CREATE TABLE products(id TEXT PRIMARY KEY,seller_id TEXT NOT NULL REFERENCES users(id),name TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',price INTEGER NOT NULL CHECK(price>0),image TEXT NOT NULL DEFAULT '',category TEXT NOT NULL DEFAULT 'others',stock INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN('pending','active','rejected','archived')),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX products_status_idx ON products(status,created_at);
CREATE TABLE orders(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),order_number TEXT NOT NULL UNIQUE,total INTEGER NOT NULL,payment_status TEXT NOT NULL DEFAULT 'pending',payment_reference TEXT NOT NULL UNIQUE,status TEXT NOT NULL DEFAULT 'pending',customer_name TEXT NOT NULL,customer_email TEXT NOT NULL,customer_phone TEXT NOT NULL,delivery_address TEXT NOT NULL,delivery_city TEXT NOT NULL,delivery_state TEXT NOT NULL,note TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE order_items(id TEXT PRIMARY KEY,order_id TEXT NOT NULL REFERENCES orders(id) ON DELETE CASCADE,product_id TEXT NOT NULL REFERENCES products(id),product_name TEXT NOT NULL,unit_price INTEGER NOT NULL,quantity INTEGER NOT NULL);
CREATE TABLE seller_applications(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),business_name TEXT NOT NULL,details TEXT NOT NULL,document_url TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'pending',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,reviewed_at TEXT);
CREATE TABLE messages(id TEXT PRIMARY KEY,sender_id TEXT NOT NULL REFERENCES users(id),body TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
